#!/usr/bin/env python3
"""
Correcao do bug: barra de busca (icone holo colapsavel) parou de
filtrar/exibir as musicas pesquisadas.

Causa raiz encontrada no repo:
- menu/albumset.xml (tela principal: Musicas/Playlists/Albuns/Artistas)
  nunca tinha o item action_search - so existia em menu/album.xml (tela
  de dentro de um album).
- Mesmo em AlbumPage.java, o item action_search do menu nunca era
  conectado a um SearchView.OnQueryTextListener. O metodo
  setupSearchMenuItem() so existia como comentario/plano no
  GalleryActivity.java, nunca foi implementado de fato. Por isso
  onSearchQueryChanged() (que already existia e já chamava
  setSearchFilter() certinho) nunca era chamado - a busca ficava
  paralisada, nao importa o que fosse digitado.

O que este script faz:
- Adiciona o item action_search a menu/albumset.xml
- Adiciona setupSearchMenuItem() em AlbumSetPage.java (tela principal)
- Adiciona setupSearchMenuItem() em AlbumPage.java (dentro de um album)

Rode este script de dentro de ~/Galeria3D (raiz do repo clonado).
Idempotente: pode rodar 2x sem quebrar nada.
Cada arquivo tocado ganha um .bak antes de ser sobrescrito.
"""

import base64
import io
import os
import shutil
import sys
import tarfile

FILES = {
    "app/src/main/res/menu/albumset.xml": "albumset.xml",
    "app/src/main/java/com/android/gallery3d/app/AlbumSetPage.java": "AlbumSetPage.java",
    "app/src/main/java/com/android/gallery3d/app/AlbumPage.java": "AlbumPage.java",
}

PAYLOAD_B64 = ""


def load_payload():
    raw = base64.b64decode(PAYLOAD_B64)
    return tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz")


def already_applied():
    path = "app/src/main/java/com/android/gallery3d/app/AlbumSetPage.java"
    if not os.path.isfile(path):
        return False
    with open(path, "r", encoding="utf-8") as f:
        return "setupSearchMenuItem" in f.read()


def main():
    if not os.path.isdir("app/src/main/java/com/android/gallery3d"):
        print("ERRO: nao encontrei app/src/main/java/com/android/gallery3d")
        print("Rode este script de dentro da pasta raiz do repo (~/Galeria3D).")
        sys.exit(1)

    if already_applied():
        print("Correcao ja aplicada anteriormente (AlbumSetPage.java ja tem")
        print("setupSearchMenuItem) - nada a fazer (script e idempotente).")
        sys.exit(0)

    tar = load_payload()
    members = {m.name.lstrip("./"): m for m in tar.getmembers()}

    for repo_path, payload_name in FILES.items():
        if payload_name not in members:
            print(f"ERRO interno: payload nao contem {payload_name}")
            sys.exit(1)

    backups = []
    try:
        for repo_path, payload_name in FILES.items():
            new_content = tar.extractfile(members[payload_name]).read()

            if os.path.isfile(repo_path):
                backup_path = repo_path + ".bak"
                shutil.copyfile(repo_path, backup_path)
                backups.append(backup_path)
                print(f"Backup criado: {backup_path}")
            else:
                os.makedirs(os.path.dirname(repo_path), exist_ok=True)

            with open(repo_path, "wb") as f:
                f.write(new_content)
            print(f"Atualizado: {repo_path}")

    except Exception as e:
        print(f"ERRO durante a aplicacao: {e}")
        print("Arquivos ja copiados tem backup .bak ao lado, revise manualmente se necessario.")
        sys.exit(1)

    print()
    print("Correcao da busca aplicada com sucesso.")
    print()
    print("O que foi feito:")
    print("- menu/albumset.xml: adicionado o icone de busca colapsavel")
    print("  (action_search), que faltava na tela principal")
    print("- AlbumSetPage.java: novo setupSearchMenuItem() liga o SearchView")
    print("  ao onSearchQueryChanged() ja existente")
    print("- AlbumPage.java: mesma correcao, dentro da tela de album")
    print()
    print("Proximo passo: recompile o app e teste a lupa em Musicas/")
    print("Playlists/Albuns/Artistas e tambem dentro de um album aberto.")


if __name__ == "__main__":
    main()
